  for (const st of MAP[inv]) { SET[nk(inv) + '||' + nk(st)] = true; }
}

const YEXTRA = ['Anicut Capital','IPV (New)','Eximius Ventures','8X Ventures','Sprout Venture Partners','GrowthCap Ventures','Blinc Invest','Dexter Ventures','BEENEXT','SamVed VC','WEH Ventures.','Mirai Ventures','Sadev Ventures','Inflection Point Ventures','Chiratae ventures','3one4 Capital','Physis Capital'];
