const rows = $input.all().map(function (i) { return i.json; });
if (rows.length < 500) { throw new Error('ABORT: PIPELINE returned only ' + rows.length + ' rows'); }

let pending = 0, alreadySent = 0, paused = 0;
const out = [];
for (const r of rows) {
  const isPaused = String(r.pause == null ? '' : r.pause).trim() !== '';
  const shared = nk(r.deal_shared) === 'yes';
  let state = 'pending';
  if (isPaused) { paused++; state = 'paused'; }
  else if (shared) { alreadySent++; state = 'sent'; }
  else { pending++; }
  const key = nk(r.investor) + '||' + nk(r.startup);
  if (SET[key]) {
    out.push({ json: {
      state: state,
      deal_id: r.deal_id,
      investor: r.investor,
      startup: r.startup,
      owner: r.owner,
      next_due: r.next_due,
      next_action: r.next_action,
      notes: r.notes,
      _total: rows.length,
      _pending: pending,
      _sent: alreadySent,
      _paused: paused
    }});
  }
}

function cnt(s) { return out.filter(function (x) { return x.json.state === s; }).length; }
function uniq(f) { const m = {}; for (const x of out) { m[x.json[f]] = 1; } return Object.keys(m); }
const summary = { SUMMARY: true,
  total_pipeline_rows: rows.length,
  pipeline_pending: pending, pipeline_sent: alreadySent, pipeline_paused: paused,
  tracker_pairs_total: Object.keys(SET).length,
  overlap_total: out.length,
  overlap_pending_would_resend: cnt('pending'),
  overlap_already_resent: cnt('sent'),
  overlap_paused: cnt('paused'),
  distinct_startups_in_overlap: uniq('startup').length,
  distinct_investors_in_overlap: uniq('investor').length,
  startups_in_overlap: uniq('startup').sort(),
  investors_in_overlap: uniq('investor').sort() };
return [{ json: summary }].concat(out);
